try:
    recursive_function()
except RecursionError:
    print("Caught RecursionError")

from rich.console import Console
from rich.traceback import Traceback

def recursive_function():
    return recursive_function()

try:
    recursive_function()
except RecursionError:
    console = Console()
    console.print(Traceback())

